xtarea-11";s:4:"type";s:8:"textarea";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:126:"What type of food do you plan to feed your pet? (Please specify brand, diet type, or whether you prefer dry, wet, or raw food)";s:11:"placeholder";s:0:"";s:10:"input_type";s:9:"paragraph";s:10:"limit_type";s:10:"characters";s:14:"default_editor";s:5:"false";}}}i:62;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-6070";s:6:"fields";a:1:{i:0;a:9:{s:10:"element_id";s:8:"radio-22";s:4:"type";s:5:"radio";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:96:"Are you financially prepared for regular check-ups, vaccinations, emergencies, and quality food?";s:11:"placeholder";s:0:"";s:10:"value_type";s:5:"radio";s:6:"layout";s:6:"inline";s:7:"options";a:2:{i:0;a:4:{s:5:"label";s:3:"Yes";s:5:"value";s:3:"yes";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-783246";}i:1;a:4:{s:5:"label";s:2:"No";s:5:"value";s:2:"no";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-573845";}}}}}i:63;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-6788";s:6:"fields";a:1:{i:0;a:5:{s:10:"element_id";s:6:"html-2";s:4:"type";s:4:"html";s:4:"cols";s:2:"12";s:11:"field_label";s:0:"";s:10:"variations";s:214:"<p><strong>Are you aware of the average costs involved in the following?</strong><br/>(If you are not aware, please ask us or do research accordingly.)<br/>Please provide your estimated costs (in AED) for each:</p>";}}}i:64;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-7041";s:6:"fields";a:1:{i:0;a:7:{s:10:"element_id";s:7:"text-23";s:4:"type";s:4:"text";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:55:"Veterinary care and vaccinations (annual and emergency)";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}}}i:65;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-5844";s:6:"fields";a:1:{i:0;a:7:{s:10:"element_id";s:7:"text-24";s:4:"type";s:4:"text";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:30:"Pet relocation (international)";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}}}i:66;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-4261";s:6:"fields";a:1:{i:0;a:7:{s:10:"element_id";s:7:"text-25";s:4:"type";s:4:"text";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:47:"Daycare, boarding, or pet sitting during travel";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}}}i:67;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-5171";s:6:"fields";a:1:{i:0;a:6:{s:10:"element_id";s:10:"section-10";s:4:"type";s:7:"section";s:4:"cols";s:2:"12";s:13:"section_title";s:18:"✍️ Declaration";s:16:"section_subtitle";s:0:"";s:14:"section_border";s:4:"none";}}}i:68;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-8375";s:6:"fields";a:1:{i:0;a:8:{s:10:"element_id";s:9:"consent-1";s:4:"type";s:7:"consent";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:0:"";s:11:"placeholder";s:0:"";s:19:"consent_description";s:277:"I confirm that the information provided is true and complete to the best of my knowledge. I understand that completing this form does not guarantee approval, and that Bubbles Pets Rescue reserves the right to deny any application if it\'s not in the best interest of the animal.";s:12:"consent_type";s:8:"checkbox";}}}i:69;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-4858";s:6:"fields";a:2:{i:0;a:7:{s:10:"element_id";s:7:"text-26";s:4:"type";s:4:"text";s:4:"cols";s:1:"6";s:8:"required";b:1;s:11:"field_label";s:18:"Emirates ID number";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}i:1;a:14:{s:10:"element_id";s:6:"date-1";s:4:"type";s:4:"date";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:4:"Date";s:11:"placeholder";s:0:"";s:10:"field_type";s:6:"picker";s:11:"date_format";s:8:"dd/mm/yy";s:4:"icon";s:4:"true";s:12:"default_date";s:4:"none";s:10:"start_year";s:0:"";s:8:"end_year";s:0:"";s:17:"start_offset_type";s:1:"+";s:15:"end_offset_type";s:1:"+";}}}i:70;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-2238";s:6:"fields";a:1:{i:0;a:5:{s:10:"element_id";s:6:"html-3";s:4:"type";s:4:"html";s:4:"cols";s:2:"12";s:11:"field_label";s:0:"";s:10:"variations";s:3110:"<h3>&#128196; Important Information Agreement Before Adoption</h3><p>Thank you for taking the time to apply for adoption. At Bubbles Pets Rescue, every animal in our care has been rescued from neglect, abandonment, surrender, or difficult circumstances. We ensure each one receives full veterinary care, socialization, and love before they are ready for adoption. Our rescues matter deeply to us.</p><p><strong>Before submitting your form, please take note of the following:</strong></p><p><strong>1. &#128062; Health &amp; care</strong><br/>All animals are sterilized, treated, vaccinated, and microchipped prior to adoption (unless medically advised otherwise). Some may need ongoing medical follow-ups, which will be discussed during the interview.</p><p><strong>2. &#127969; Home visits &amp; screening</strong><br/>We may request a home visit or video call before approving an adoption to ensure a safe and suitable environment.</p><p><strong>3. Adoption fees</strong><br/>Our adoption fees vary for each rescue and range between AED 800 and AED 4,000. These fees are a reimbursement that supports the ongoing rescue work and care of our animals. They are non-refundable, except during the trial period, which will be discussed during the interview.</p><p><strong>4. &#128683; Rehoming policy</strong><br/>Rehoming, selling, or giving away an adopted animal is strictly prohibited. If, for any reason, your adoption does not work out or your life circumstances change, you are required to inform Bubbles Pets Rescue immediately. You must contact us to discuss the situation before making any decision to rehome the animal. In such cases, the adopted animal must be returned to Bubbles Pets Rescue, and we will work together to ensure the best possible outcome for the animal. All rescued animals remain microchipped under Bubbles Pets Rescue\'s name to ensure their lifelong safety and traceability. Any unauthorized rehoming will result in appropriate action being taken by the organization.</p><p><strong>5. &#128172; Response time &amp; application review</strong><br/>Please note that filling out this form does not guarantee adoption. Once your form is reviewed and if approved, we will contact you to schedule an interview and meet the animal you are interested in. Because we are a small volunteer team, responses may take 1 to 3 days, and occasionally up to one week, depending on workload and the rescue\'s situation. You are welcome to follow up on your application at any time. If your form is not selected, we may not always be able to notify you, especially for high-demand rescues. This may be due to finding a better home match or suitability for the specific animal. You are encouraged to follow up personally for an update on your application status.</p><p><strong>6. &#128248; Sharing adoption stories</strong><br/>We may kindly request photos or short updates after adoption to celebrate and share successful rescue stories on our pages. Family or pet pictures are completely optional, but they help us spread awareness and joy by showing happy endings made possible through adoption.</p>";}}}i:71;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-7999";s:6:"fields";a:1:{i:0;a:6:{s:10:"element_id";s:10:"section-11";s:4:"type";s:7:"section";s:4:"cols";s:2:"12";s:13:"section_title";s:26:"Acknowledgment & Signature";s:16:"section_subtitle";s:0:"";s:14:"section_border";s:4:"none";}}}i:72;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-3888";s:6:"fields";a:1:{i:0;a:8:{s:10:"element_id";s:9:"consent-2";s:4:"type";s:7:"consent";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:0:"";s:11:"placeholder";s:0:"";s:19:"consent_description";s:137:"I confirm that I have read, understood, and agree to the Important Information Agreement Before Adoption provided by Bubbles Pets Rescue.";s:12:"consent_type";s:8:"checkbox";}}}i:73;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-1587";s:6:"fields";a:1:{i:0;a:7:{s:10:"element_id";s:7:"text-27";s:4:"type";s:4:"text";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:21:"Applicant\'s full name";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}}}i:74;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-3755";s:6:"fields";a:1:{i:0;a:9:{s:10:"element_id";s:11:"signature-1";s:4:"type";s:9:"signature";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:9:"Signature";s:11:"placeholder";s:0:"";s:4:"icon";s:4:"true";s:6:"height";s:3:"150";s:9:"thickness";s:1:"2";}}}i:75;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-1376";s:6:"fields";a:1:{i:0;a:5:{s:10:"element_id";s:6:"html-4";s:4:"type";s:4:"html";s:4:"cols";s:2:"12";s:11:"field_label";s:0:"";s:10:"variations";s:286:"<h3>&#128274; Confidentiality Notice</h3><p>All personal information provided in this form will remain strictly confidential and used solely for adoption screening and rescue-related purposes by Bubbles Pets Rescue. It will not be shared, published, or disclosed to any third party.</p>";}}}i:76;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648777652-8900";s:6:"fields";a:1:{i:0;a:5:{s:10:"element_id";s:6:"html-5";s:4:"type";s:4:"html";s:4:"cols";s:2:"12";s:11:"field_label";s:0:"";s:10:"variations";s:316:"<h3>&#128222; Contact Us</h3><p>&#128241; WhatsApp: +971 50 808 3083<br/>&#128248; Instagram: @Bubbles.petsrescue<br/>&#128216; Facebook: Bubbles.petsrescue<br/>&#128231; Email: LittleAngelsUae@outlook.com</p><p><strong>Thank you for choosing adoption and giving a rescue animal a second chance at life.</strong></p>";}}}}s:8:"settings";a:27:{s:8:"formName";s:42:"Adoption Application - Bubbles Pets Rescue";s:7:"version";s:3:"1.0";s:17:"pagination-header";s:3:"nav";s:26:"cform-section-border-color";s:7:"#E9E9E9";s:11:"form-expire";s:9:"no_expire";s:17:"form-border-style";s:4:"none";s:12:"form-padding";s:0:"";s:11:"form-border";s:0:"";s:12:"fields-style";s:4:"open";s:16:"fi